public class Main {
    static String describe(Object value) {
        return value instanceof String s
                ? s.substring(0, Math.min(2, s.length()))
                : String.valueOf(value);
    }

    public static void main(String[] args) {
        System.out.print(describe("Java") + ":");
        System.out.print(describe(12));
    }
}

public class Main {
    static String check(Object value) {
        if (!(value instanceof String s) || s.isEmpty()) {
            return "N";
        }
        return s.substring(0, 1);
    }

    public static void main(String[] args) {
        System.out.print(check("Java") + ":");
        System.out.print(check("") + ":");
        System.out.print(check(10));
    }
}

